import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(import.meta.url));
const root=path.resolve(here,'../..');
const output=path.join(root,'.local/design/plugin');
// The ID comes from a local manifest generated by Figma, never from a committed example.
const input=process.argv[2];
if(!input) throw Error('Usage: node tools/figma-export/build.mjs .local/figma-created/manifest.json');
const id=JSON.parse(fs.readFileSync(input,'utf8')).id;
if(typeof id!=='string'||!/^\d+$/.test(id))throw Error('Use a manifest ID created by Figma');
for(const dir of ['.local','.local/design','.local/design/plugin']){
  const p=path.join(root,dir); if(fs.existsSync(p)&&fs.lstatSync(p).isSymbolicLink())throw Error('Refusing symlink output');
}
fs.mkdirSync(output,{recursive:true});
for(const filename of ['code.js','ui.html','manifest.json']){
  if(fs.existsSync(path.join(output,filename))&&fs.lstatSync(path.join(output,filename)).isSymbolicLink())throw Error('Refusing symlink output file');
}
fs.copyFileSync(path.join(here,'code.js'),path.join(output,'code.js'));
fs.writeFileSync(path.join(output,'ui.html'),fs.readFileSync(path.join(here,'ui.html'),'utf8').replace('/* ZIP_IMPLEMENTATION */',fs.readFileSync(path.join(here,'zip.js'),'utf8')));
fs.writeFileSync(path.join(output,'manifest.json'),JSON.stringify({name:'DejaView private export',id,api:'1.0.0',editorType:['figma'],main:'code.js',ui:'ui.html',documentAccess:'dynamic-page',networkAccess:{allowedDomains:['none']}},null,2)+'\n');
console.log('Built local plugin in .local/design/plugin; import its manifest in Figma desktop.');
